def transform(grid):
    nrows, ncols = len(grid), len(grid[0])
    n = next(k for k in range(1, 31) if k * k + k - 1 == nrows)
    pitch = n + 1

    out = [row[:] for row in grid]
    for r in range(nrows):
        for c in range(ncols):
            if out[r][c] == 3:
                out[r][c] = 0

    # Find the all-3 band and its macro-tile index.
    stripe = None
    for r in range(nrows):
        if all(grid[r][c] == 3 for c in range(ncols)):
            stripe = ("h", r // pitch)
            break
    if stripe is None:
        for c in range(ncols):
            if all(grid[r][c] == 3 for r in range(nrows)):
                stripe = ("v", c // pitch)
                break

    orient, k = stripe

    # Macro-tile occupancy outside the stripe.
    occ = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if (orient == "h" and i == k) or (orient == "v" and j == k):
                continue
            r0, c0 = i * pitch, j * pitch
            occ[i][j] = any(
                grid[r0 + a][c0 + b] == 2
                for a in range(n) for b in range(n)
            )

    # Choose the tile whose internal pattern matches the visible macro pattern.
    best_mask, best_score = None, -1
    for i in range(n):
        for j in range(n):
            if (orient == "h" and i == k) or (orient == "v" and j == k):
                continue
            r0, c0 = i * pitch, j * pitch
            mask = [[grid[r0 + a][c0 + b] == 2 for b in range(n)]
                    for a in range(n)]
            score = sum(
                mask[a][b] == occ[a][b]
                for a in range(n) for b in range(n)
                if not ((orient == "h" and a == k) or
                        (orient == "v" and b == k))
            )
            if score > best_score:
                best_mask, best_score = mask, score

    # Highlight each existing tile at the cell indexed by its macro position.
    for i in range(n):
        for j in range(n):
            if (orient == "h" and i == k) or (orient == "v" and j == k):
                continue
            r, c = i * pitch + i, j * pitch + j
            if out[r][c] == 2:
                out[r][c] = 8

    # Fill the stripe according to the repeated motif, highlighting its index cell.
    for i in range(n):
        for j in range(n):
            if not ((orient == "h" and i == k) or
                    (orient == "v" and j == k)):
                continue
            if not best_mask[i][j]:
                continue
            r0, c0 = i * pitch, j * pitch
            for a in range(n):
                for b in range(n):
                    if best_mask[a][b]:
                        out[r0 + a][c0 + b] = 2
            out[r0 + i][c0 + j] = 8

    return out
